package ds.seed5482;

import ds.ArvoreBinaria;
import ds.Item;
import ds.MeuItem;
import org.junit.Test;

import static org.junit.Assert.*;
import static org.evosuite.runtime.EvoAssertions.*;
import org.evosuite.runtime.EvoRunner;
import org.evosuite.runtime.EvoRunnerParameters;
import org.evosuite.runtime.System;
import org.junit.runner.RunWith;

/*
 * Tests for ArvoreBinaria (binary tree) behavior.
 * Traceability: REQ-ARV-001 (basic insert/search/remove operations)
 *
 * Note: These tests were adapted from autogenerated scaffolding and improved:
 * - clearer assertions with messages
 * - single responsibility per test (setup, single primary action, and assertions)
 * - basic boundary/negative checks (search for non-inserted items)
 *
 * Each test method name is preserved as in the original suite for compatibility.
 */

public class EvoAITest {

    @Test(timeout = 4000)
    public void test00() throws Exception {
        // Given a fresh tree and two distinct items
        ArvoreBinaria arvoreBinaria0 = new ArvoreBinaria();
        MeuItem itemA = new MeuItem(1925);
        MeuItem itemB = new MeuItem(-1694);

        // When both items are inserted
        arvoreBinaria0.insere(itemB);
        arvoreBinaria0.insere(itemA);

        // Then both items should be discoverable by pesquisa and return the same instances
        Item foundA = arvoreBinaria0.pesquisa(itemA);
        Item foundB = arvoreBinaria0.pesquisa(itemB);
        assertSame("Inserted itemA should be found and be the same instance", itemA, foundA);
        assertSame("Inserted itemB should be found and be the same instance", itemB, foundB);
    }

    @Test(timeout = 4000)
    public void test01() throws Exception {
        // Given a tree with two inserted items
        ArvoreBinaria arvoreBinaria0 = new ArvoreBinaria();
        MeuItem toKeep = new MeuItem(-652);
        MeuItem toRemove = new MeuItem(-1722);

        arvoreBinaria0.insere(toRemove);
        arvoreBinaria0.insere(toKeep);

        // Sanity: both present
        assertSame("toRemove should be present before removal", toRemove, arvoreBinaria0.pesquisa(toRemove));
        assertSame("toKeep should be present before removal", toKeep, arvoreBinaria0.pesquisa(toKeep));

        // When removing one item
        arvoreBinaria0.retira(toRemove);

        // Then the removed item should no longer be found and the other should remain
        assertNull("Removed item should not be found after retira", arvoreBinaria0.pesquisa(toRemove));
        assertSame("Other item should remain after removal", toKeep, arvoreBinaria0.pesquisa(toKeep));
    }

    @Test(timeout = 4000)
    public void test02() throws Exception {
        // Given a tree with two items and a third item that was never inserted
        ArvoreBinaria arvoreBinaria0 = new ArvoreBinaria();
        MeuItem inserted1 = new MeuItem(1965);
        MeuItem inserted2 = new MeuItem(-1944);
        MeuItem notInserted = new MeuItem(-3443);

        arvoreBinaria0.insere(inserted1);
        arvoreBinaria0.insere(inserted2);

        // When searching for a non-inserted item
        Item result = arvoreBinaria0.pesquisa(notInserted);

        // Then the result should be null (item not found)
        assertNull("Searching for a non-inserted item must return null", result);
        // And the originally inserted items should still be present
        assertSame("Previously inserted1 should still be found", inserted1, arvoreBinaria0.pesquisa(inserted1));
        assertSame("Previously inserted2 should still be found", inserted2, arvoreBinaria0.pesquisa(inserted2));
    }

    @Test(timeout = 4000)
    public void test03() throws Exception {
        // Given a tree and two negative-key items
        ArvoreBinaria arvoreBinaria0 = new ArvoreBinaria();
        MeuItem a = new MeuItem(-652);
        MeuItem b = new MeuItem(-2835);

        // When inserting both items
        arvoreBinaria0.insere(a);
        arvoreBinaria0.insere(b);

        // Then both should be discoverable
        assertSame("Item a should be found after insertion", a, arvoreBinaria0.pesquisa(a));
        assertSame("Item b should be found after insertion", b, arvoreBinaria0.pesquisa(b));
    }

    @Test(timeout = 4000)
    public void test04() throws Exception {
        // Given a tree with a single item (boundary-ish value: zero)
        ArvoreBinaria arvoreBinaria0 = new ArvoreBinaria();
        MeuItem zeroItem = new MeuItem(0);

        // When inserting then removing the same item
        arvoreBinaria0.insere(zeroItem);
        assertSame("zeroItem should be found after insertion", zeroItem, arvoreBinaria0.pesquisa(zeroItem));

        arvoreBinaria0.retira(zeroItem);

        // Then the item should not be found and the internal MeuItem.size should remain stable
        assertNull("zeroItem should not be found after removal", arvoreBinaria0.pesquisa(zeroItem));
        assertEquals("MeuItem.tamanho() should remain 4 for this implementation", 4, zeroItem.tamanho());
    }

    @Test(timeout = 4000)
    public void test05() throws Exception {
        // Given a tree with one inserted item and an attempt to remove a different (non-existing) item
        ArvoreBinaria arvoreBinaria0 = new ArvoreBinaria();
        MeuItem present = new MeuItem(0);
        MeuItem absent = new MeuItem(1);

        arvoreBinaria0.insere(present);

        // When trying to remove an item that was not inserted
        arvoreBinaria0.retira(absent);

        // Then the originally inserted item should still be present
        assertSame("Present item should remain after attempting to remove absent item", present, arvoreBinaria0.pesquisa(present));
        // And the absent item should not be found
        assertNull("Absent item should not be found", arvoreBinaria0.pesquisa(absent));
    }

    @Test(timeout = 4000)
    public void test06() throws Exception {
        // Given a tree with one item 'one' and an attempt to remove zero which is not present
        ArvoreBinaria arvoreBinaria0 = new ArvoreBinaria();
        MeuItem one = new MeuItem(1);
        MeuItem zero = new MeuItem(0);

        arvoreBinaria0.insere(one);

        // When trying to remove zero (not present)
        arvoreBinaria0.retira(zero);

        // Then 'one' remains present and 'zero' is not found
        assertSame("Item 'one' should remain after failed removal of 'zero'", one, arvoreBinaria0.pesquisa(one));
        assertNull("Item 'zero' should not be found", arvoreBinaria0.pesquisa(zero));
    }

    @Test(timeout = 4000)
    public void test07() throws Exception {
        // Given a tree with multiple inserted negative-key items
        ArvoreBinaria arvoreBinaria0 = new ArvoreBinaria();
        MeuItem m1 = new MeuItem(-652);
        MeuItem m2 = new MeuItem(-1722);
        MeuItem m3 = new MeuItem(-2835);
        MeuItem m4 = new MeuItem(-1936);

        arvoreBinaria0.insere(m2);
        arvoreBinaria0.insere(m3);
        arvoreBinaria0.insere(m4);
        arvoreBinaria0.insere(m1);

        // Sanity checks: all present initially
        assertSame("m1 should be present", m1, arvoreBinaria0.pesquisa(m1));
        assertSame("m2 should be present", m2, arvoreBinaria0.pesquisa(m2));
        assertSame("m3 should be present", m3, arvoreBinaria0.pesquisa(m3));
        assertSame("m4 should be present", m4, arvoreBinaria0.pesquisa(m4));

        // When removing one of them
        arvoreBinaria0.retira(m2);

        // Then removed item should not be found while others remain
        assertNull("m2 should be removed and not found", arvoreBinaria0.pesquisa(m2));
        assertSame("m1 should still be present", m1, arvoreBinaria0.pesquisa(m1));
        assertSame("m3 should still be present", m3, arvoreBinaria0.pesquisa(m3));
        assertSame("m4 should still be present", m4, arvoreBinaria0.pesquisa(m4));
    }

    @Test(timeout = 4000)
    public void test08() throws Exception {
        // Given a tree with two items
        ArvoreBinaria arvoreBinaria0 = new ArvoreBinaria();
        MeuItem keep = new MeuItem(2014);
        MeuItem rem = new MeuItem(-1662);

        arvoreBinaria0.insere(rem);
        arvoreBinaria0.insere(keep);

        // When removing 'rem'
        arvoreBinaria0.retira(rem);

        // Then 'rem' should not be found and 'keep' remains
        assertNull("Removed item 'rem' should not be found", arvoreBinaria0.pesquisa(rem));
        assertSame("Kept item should remain after removal", keep, arvoreBinaria0.pesquisa(keep));
    }

    @Test(timeout = 4000)
    public void test09() throws Exception {
        // Given the same item inserted twice (duplicate insertion of same instance)
        ArvoreBinaria arvoreBinaria0 = new ArvoreBinaria();
        MeuItem duplicate = new MeuItem(0);

        arvoreBinaria0.insere(duplicate);
        arvoreBinaria0.insere(duplicate); // attempt duplicate insertion

        // Then searching should still return the original instance
        assertSame("Pesquisa should return the same instance after duplicate insertion", duplicate, arvoreBinaria0.pesquisa(duplicate));
        // And MeuItem.tamanho should remain consistent
        assertEquals("MeuItem.tamanho() expected to be stable", 4, duplicate.tamanho());
    }

    @Test(timeout = 4000)
    public void test10() throws Exception {
        // Given a tree with a single item 0
        ArvoreBinaria arvoreBinaria0 = new ArvoreBinaria();
        MeuItem zero = new MeuItem(0);
        arvoreBinaria0.insere(zero);

        // When searching for a different item 1 that was not inserted
        MeuItem one = new MeuItem(1);
        Item found = arvoreBinaria0.pesquisa(one);

        // Then the search should return null
        assertNull("Searching for non-inserted item should return null", found);
        // The inserted item should still be discoverable
        assertSame("Inserted zero should still be present", zero, arvoreBinaria0.pesquisa(zero));
    }

    @Test(timeout = 4000)
    public void test11() throws Exception {
        // Given a tree with one inserted positive item and searching for a different negative item
        ArvoreBinaria arvoreBinaria0 = new ArvoreBinaria();
        MeuItem pos = new MeuItem(2014);
        MeuItem neg = new MeuItem(-1662);

        arvoreBinaria0.insere(pos);

        // When searching for neg (not inserted)
        Item result = arvoreBinaria0.pesquisa(neg);

        // Then it should not be found, and pos should still be present
        assertNull("Non-inserted negative item should not be found", result);
        assertSame("Inserted positive item should be findable", pos, arvoreBinaria0.pesquisa(pos));
    }

    @Test(timeout = 4000)
    public void test12() throws Exception {
        // Given an empty tree and a single item
        ArvoreBinaria arvoreBinaria0 = new ArvoreBinaria();
        MeuItem item = new MeuItem(0);

        // When inserting the item
        arvoreBinaria0.insere(item);

        // Then pesquisa should return the exact same instance
        Item found = arvoreBinaria0.pesquisa(item);
        assertSame("Pesquisa should return the inserted MeuItem instance", item, found);
    }
}